package firecracker

import("context";"crypto/sha256";"encoding/json";"errors";"fmt";"io";"os";"os/exec";"path/filepath";"runtime";"strconv";"strings";"syscall";"time";"github.com/eutelic/runnerhub/internal/core";"github.com/eutelic/runnerhub/internal/hostinfo";"github.com/eutelic/runnerhub/internal/provider")
type Config struct{Binary string;KernelImage string;RootFS string;StateDir string;HostID string;GuestBootArgs string;MkfsBinary string;IPBinary string;Bridge string};type Provider struct{cfg Config}
func New(c Config)(*Provider,error){if c.Binary==""{c.Binary="firecracker"};if c.StateDir==""{c.StateDir="/var/lib/runnerhub/firecracker"};if c.MkfsBinary==""{c.MkfsBinary="mkfs.ext4"};if c.IPBinary==""{c.IPBinary="ip"};if c.KernelImage==""||c.RootFS==""{return nil,errors.New("firecracker kernel and rootfs are required")};if strings.TrimSpace(c.Bridge)==""{return nil,errors.New("firecracker bridge is required for GitHub network access")};return &Provider{cfg:c},nil}
func(p *Provider)Capabilities(ctx context.Context)(provider.Capabilities,error){if runtime.GOOS!="linux"{return provider.Capabilities{},errors.New("firecracker requires linux")};if _,err:=os.Stat("/dev/kvm");err!=nil{return provider.Capabilities{},errors.New("/dev/kvm unavailable")};if err:=exec.CommandContext(ctx,p.cfg.Binary,"--version").Run();err!=nil{return provider.Capabilities{},err};if err:=exec.CommandContext(ctx,p.cfg.IPBinary,"link","show","dev",p.cfg.Bridge).Run();err!=nil{return provider.Capabilities{},fmt.Errorf("firecracker bridge %q unavailable: %w",p.cfg.Bridge,err)};return provider.Capabilities{Provider:"firecracker",OS:"linux",Architecture:runtime.GOARCH,Capacity:hostinfo.Capacity(p.cfg.StateDir),IsolationModes:[]core.IsolationMode{core.IsolationMicroVM},Features:map[string]bool{"kvm":true,"ephemeralRootFS":true,"dockerInsideVM":true,"perWorkerTap":true},Labels:map[string]string{"isolation.microvm":"true"}},nil}
func(p *Provider)Validate(_ context.Context,s provider.WorkerSpec)error{if strings.TrimSpace(s.WorkerID)==""||strings.TrimSpace(s.RunnerName)==""{return errors.New("worker id and runner name are required")};if s.Isolation!=core.IsolationMicroVM{return errors.New("firecracker provider requires microvm isolation")};if s.JITConfig==""{return errors.New("jit config required")};if s.Resources.GPUs>0{return errors.New("gpu passthrough is not enabled for firecracker provider")};return nil}
func(p *Provider)Create(ctx context.Context,s provider.WorkerSpec)(provider.WorkerHandle,error){if err:=p.Validate(ctx,s);err!=nil{return provider.WorkerHandle{},err};key:=safe(s.WorkerID);if key==""{return provider.WorkerHandle{},errors.New("invalid worker id")};h:=provider.WorkerHandle{ProviderID:key,HostID:p.cfg.HostID};if alive,_:=p.alive(h);alive{return h,nil};dir:=filepath.Join(p.cfg.StateDir,key);if err:=os.MkdirAll(dir,0700);err!=nil{return provider.WorkerHandle{},err};cleanup:=func(){p.teardownTap(context.Background(),key);_=os.RemoveAll(dir)};root:=filepath.Join(dir,"rootfs.ext4");if err:=copyFile(p.cfg.RootFS,root);err!=nil{cleanup();return provider.WorkerHandle{},err};seed,err:=p.buildSeed(ctx,dir,s.JITConfig);if err!=nil{cleanup();return provider.WorkerHandle{},err};tap,err:=p.setupTap(ctx,key);if err!=nil{cleanup();return provider.WorkerHandle{},err};mem:=s.Resources.MemoryBytes/(1024*1024);if mem<512{mem=512};vcpus:=s.Resources.CPUMillis/1000;if vcpus<1{vcpus=1};cfg:=map[string]any{"boot-source":map[string]any{"kernel_image_path":p.cfg.KernelImage,"boot_args":defaultString(p.cfg.GuestBootArgs,"console=ttyS0 reboot=k panic=1 pci=off")},"drives":[]map[string]any{{"drive_id":"rootfs","path_on_host":root,"is_root_device":true,"is_read_only":false},{"drive_id":"runnerhub-seed","path_on_host":seed,"is_root_device":false,"is_read_only":true}},"network-interfaces":[]map[string]any{{"iface_id":"eth0","guest_mac":guestMAC(key),"host_dev_name":tap}},"machine-config":map[string]any{"vcpu_count":vcpus,"mem_size_mib":mem}};b,_:=json.Marshal(cfg);cfgPath:=filepath.Join(dir,"vm.json");if err:=os.WriteFile(cfgPath,b,0600);err!=nil{cleanup();return provider.WorkerHandle{},err};cmd:=exec.CommandContext(ctx,p.cfg.Binary,"--no-api","--config-file",cfgPath);logf,err:=os.OpenFile(filepath.Join(dir,"console.log"),os.O_CREATE|os.O_WRONLY|os.O_APPEND,0600);if err!=nil{cleanup();return provider.WorkerHandle{},err};cmd.Stdout=logf;cmd.Stderr=logf;if err:=cmd.Start();err!=nil{_=logf.Close();cleanup();return provider.WorkerHandle{},err};if err:=os.WriteFile(filepath.Join(dir,"pid"),[]byte(strconv.Itoa(cmd.Process.Pid)),0600);err!=nil{_=cmd.Process.Kill();cleanup();return provider.WorkerHandle{},err};return h,nil}
func(p *Provider)setupTap(ctx context.Context,key string)(string,error){tap:=tapName(key);if err:=exec.CommandContext(ctx,p.cfg.IPBinary,"link","show","dev",tap).Run();err!=nil{if out,err:=exec.CommandContext(ctx,p.cfg.IPBinary,"tuntap","add","dev",tap,"mode","tap").CombinedOutput();err!=nil{return "",fmt.Errorf("create tap: %w: %s",err,strings.TrimSpace(string(out)))}};if out,err:=exec.CommandContext(ctx,p.cfg.IPBinary,"link","set","dev",tap,"master",p.cfg.Bridge).CombinedOutput();err!=nil{return "",fmt.Errorf("attach tap to bridge: %w: %s",err,strings.TrimSpace(string(out)))};if out,err:=exec.CommandContext(ctx,p.cfg.IPBinary,"link","set","dev",tap,"up").CombinedOutput();err!=nil{return "",fmt.Errorf("bring tap up: %w: %s",err,strings.TrimSpace(string(out)))};return tap,nil}
func(p *Provider)teardownTap(ctx context.Context,key string){_=exec.CommandContext(ctx,p.cfg.IPBinary,"link","delete","dev",tapName(key)).Run()}
func(p *Provider)buildSeed(ctx context.Context,dir,jitConfig string)(string,error){seedDir:=filepath.Join(dir,"seed");if err:=os.MkdirAll(seedDir,0700);err!=nil{return "",err};if err:=os.WriteFile(filepath.Join(seedDir,"jitconfig"),[]byte(jitConfig),0600);err!=nil{return "",err};if err:=os.WriteFile(filepath.Join(seedDir,"manifest"),[]byte("RUNNERHUB_SEED_V1\n"),0600);err!=nil{return "",err};seed:=filepath.Join(dir,"seed.ext4");f,err:=os.OpenFile(seed,os.O_CREATE|os.O_RDWR|os.O_TRUNC,0600);if err!=nil{return "",err};if err:=f.Truncate(16<<20);err!=nil{_=f.Close();return "",err};_=f.Close();cmd:=exec.CommandContext(ctx,p.cfg.MkfsBinary,"-q","-F","-d",seedDir,seed);if out,err:=cmd.CombinedOutput();err!=nil{return "",fmt.Errorf("build firecracker seed: %w: %s",err,strings.TrimSpace(string(out)))};return seed,nil}
func(p *Provider)Inspect(_ context.Context,h provider.WorkerHandle)(provider.WorkerState,error){alive,err:=p.alive(h);if err!=nil{if errors.Is(err,os.ErrNotExist){return provider.WorkerState{State:core.WorkerDeleted},nil};return provider.WorkerState{},err};if alive{return provider.WorkerState{State:core.WorkerReady,SafeDetail:"microvm process running"},nil};return provider.WorkerState{State:core.WorkerCompleted,SafeDetail:"microvm process exited"},nil}
func(p *Provider)Stop(ctx context.Context,h provider.WorkerHandle)error{key:=safe(h.ProviderID);if key==""{return errors.New("firecracker handle required")};pid,err:=p.pid(h);if err!=nil{return nil};proc,_:=os.FindProcess(pid);_=proc.Signal(syscall.SIGTERM);deadline:=time.Now().Add(5*time.Second);for time.Now().Before(deadline){if err:=proc.Signal(syscall.Signal(0));err!=nil{return nil};select{case<-ctx.Done():return ctx.Err();case<-time.After(100*time.Millisecond):}};return proc.Kill()}
func(p *Provider)Delete(ctx context.Context,h provider.WorkerHandle)error{key:=safe(h.ProviderID);if key==""{return errors.New("firecracker handle required")};_=p.Stop(ctx,h);p.teardownTap(ctx,key);return os.RemoveAll(filepath.Join(p.cfg.StateDir,key))}
func(p *Provider)alive(h provider.WorkerHandle)(bool,error){pid,err:=p.pid(h);if err!=nil{return false,err};proc,err:=os.FindProcess(pid);if err!=nil{return false,err};return proc.Signal(syscall.Signal(0))==nil,nil}
func(p *Provider)pid(h provider.WorkerHandle)(int,error){key:=safe(h.ProviderID);if key==""{return 0,errors.New("firecracker handle required")};b,err:=os.ReadFile(filepath.Join(p.cfg.StateDir,key,"pid"));if err!=nil{return 0,err};return strconv.Atoi(strings.TrimSpace(string(b)))}
func copyFile(src,dst string)error{in,err:=os.Open(src);if err!=nil{return err};defer in.Close();out,err:=os.OpenFile(dst,os.O_CREATE|os.O_TRUNC|os.O_WRONLY,0600);if err!=nil{return err};_,cpErr:=io.Copy(out,in);closeErr:=out.Close();if cpErr!=nil{return cpErr};return closeErr}
func safe(s string)string{s=strings.Map(func(r rune)rune{if r>='a'&&r<='z'||r>='A'&&r<='Z'||r>='0'&&r<='9'||r=='-'{return r};return '-'},s);return strings.Trim(s,"-")}
func tapName(key string)string{sum:=sha256.Sum256([]byte(key));return fmt.Sprintf("rh%x",sum[:6])}
func guestMAC(key string)string{sum:=sha256.Sum256([]byte("mac:"+key));return fmt.Sprintf("02:%02x:%02x:%02x:%02x:%02x",sum[0],sum[1],sum[2],sum[3],sum[4])}
func defaultString(a,b string)string{if a!=""{return a};return b}
